async function networkFetch(url,options){for(let attempt=0;attempt<2;attempt++){try{return await fetch(url,options);}catch(error){if(attempt===1)throw error;await new Promise(resolve=>setTimeout(resolve,150));}}}
async function api(url,options){const res=await networkFetch(url,options);if(!res.ok){let text=await res.text();try{text=JSON.parse(text).error||text;}catch{}throw Error(text||`${res.status} ${res.statusText}`);}return res.json();}
function post(url,data){return fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});}
function markDirty(){state.dirty=true;$('dirty').className='changed';$('project-state').textContent='Есть несохранённые изменения';}
function currentSnapshot(){return clone(state.model);}
function remember(before=currentSnapshot()){state.history.push(before);if(state.history.length>50)state.history.shift();state.future=[];updateHistory();markDirty();}
function updateHistory(){$('undo').disabled=!state.history.length;$('redo').disabled=!state.future.length;}
function syncModel(){if(state.model)state.project.scenes[state.model.name]=state.model;}
