function applyTransform(node,object){const t=object.editorTransform||{};node.rotation.copy(toEuler(t.rotation));node.scale.fromArray(vector(t.scale,[1,1,1]));const pivot=new THREE.Vector3().fromArray(node.userData.editorPivot||[0,0,0]).multiply(node.scale).applyQuaternion(node.quaternion);node.position.fromArray(vector(t.position)).add(pivot);node.visible=object.editorVisible!==false;node.updateMatrixWorld(true);}
