function updateSelectionBox(){if(selectionBox){scene.remove(selectionBox);selectionBox.dispose();selectionBox=null;}const node=selectedNode();if(node){selectionBox=new THREE.BoxHelper(node,0xc3f478);selectionBox.material.depthTest=false;selectionBox.material.depthWrite=false;selectionBox.renderOrder=10000;scene.add(selectionBox);}}
function choose(id){state.selected=id;const node=nodes.get(id);transform.detach();if(node&&!gameCameraMode&&$('select-tool').classList.contains('active')===false)transform.attach(node);updateSelectionBox();renderTree();renderInspector();refreshAnimationClips();}
