function renderTree(){if(!state.model)return;const query=$('search').value.toLocaleLowerCase();const list=state.model.objects.filter(o=>(o.name+' '+o.id+' '+o.group).toLocaleLowerCase().includes(query));$('object-count').textContent=state.model.objects.length;let lastGroup=null;const frag=document.createDocumentFragment();for(const object of list){const group=object.editorImported?'Импортированные':({static_objects:'Декорации',dynamic_objects:'Персонажи и предметы',interface_objects:'Интерфейс'}[object.group]||object.group||'Объекты');if(lastGroup!==group){const label=document.createElement('div');label.className='group-label';label.textContent=group;frag.append(label);lastGroup=group;}const row=document.createElement('div');row.className='tree-row'+(state.selected===object.id?' selected':'')+(object.editorVisible===false?' hidden-object':'');row.dataset.id=object.id;row.setAttribute('role','treeitem');row.setAttribute('aria-selected',String(state.selected===object.id));row.innerHTML=`<span class="object-icon">${object.lods?.length||object.editorMesh?'◇':'⌖'}</span><span class="object-title">${esc(object.name||object.id)}</span><button class="visibility" title="Скрыть / показать">${object.editorVisible===false?'○':'◉'}</button>`;row.addEventListener('click',()=>choose(object.id));row.addEventListener('dblclick',()=>{choose(object.id);frameObject();});row.querySelector('button').addEventListener('click',event=>{event.stopPropagation();remember();object.editorVisible=object.editorVisible===false;nodes.get(object.id).visible=object.editorVisible;renderTree();});frag.append(row);}$('object-tree').replaceChildren(frag);}
