async function renderObject(object,serial){const node=new THREE.Group();node.name=object.name||object.id;node.userData.editorId=object.id;let files=[];if(object.editorMesh)files=[object.editorMesh];else{const names=meshNames(object);for(const name of names){try{files.push(await getMesh(name));}catch(error){state.failedMeshes.push({object:object.name,mesh:name,error:error.message});console.warn(name,error);}}}if(serial!==loadingSerial)return null;const bones=boneMatrices(object);for(const data of files){for(const part of data.parts||[]){const positions=part.positions||[],indices=part.indices||Array.from({length:positions.length/3},(_,i)=>i),faceUV=part.uv||[];const expanded=[],uvs=[];const p=new THREE.Vector3();for(let i=0;i<indices.length;i++){const vi=indices[i];p.fromArray(positions,vi*3);if(!object.editorImported){const id=part.vertexBones?.[vi];if(id!==undefined)p.applyMatrix4(bones.get(String(id))||new THREE.Matrix4());}expanded.push(p.x,p.y,p.z);if(faceUV.length===indices.length*2)uvs.push(faceUV[i*2],faceUV[i*2+1]);else if(faceUV.length===positions.length/3*2)uvs.push(faceUV[vi*2],faceUV[vi*2+1]);else uvs.push(0,0);}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(expanded,3));geometry.setAttribute('uv',new THREE.Float32BufferAttribute(uvs,2));geometry.computeVertexNormals();const names=part.materialNames?.length?part.materialNames:[''];const materials=await Promise.all(names.map(n=>material(n,data.materials?.find(m=>m.name===n))));if(part.faceMaterials?.length){let start=0,prev=part.faceMaterials[0]||0;for(let f=1;f<=indices.length/3;f++){const next=part.faceMaterials[f]||0;if(next!==prev||f===indices.length/3){geometry.addGroup(start*3,(f-start)*3,Math.min(prev,materials.length-1));start=f;prev=next;}}}const mesh=new THREE.Mesh(geometry,materials.length>1?materials:materials[0]);mesh.userData.rigid={raw:Float32Array.from(indices.flatMap(vi=>positions.slice(vi*3,vi*3+3))),boneIds:Int32Array.from(indices.map(vi=>part.vertexBones?.[vi]??0)),bind:geometry.attributes.position.array.slice()};mesh.name=part.name||object.name;node.add(mesh);}}
await renderNativePlanes(object,node,bones);await renderNativeEmitters(object,node,bones);
if(!node.children.length){const rootBone=(object.bones||[]).find(b=>Number(b.parent)<0)||(object.bones||[])[0];const marker=new THREE.AxesHelper(.3);marker.name='Точка объекта';marker.userData.editorHelper=true;if(rootBone){const pos=bones.get(String(rootBone.id??0));if(pos)marker.position.setFromMatrixPosition(pos);}node.add(marker);}
// Keep the gizmo at the object's centre while serializing an ordinary world delta.
node.updateMatrixWorld(true);const bounds=new THREE.Box3().setFromObject(node);const pivot=bounds.isEmpty()?new THREE.Vector3():bounds.getCenter(new THREE.Vector3());node.userData.editorPivot=pivot.toArray();const pivotGroup=new THREE.Group();pivotGroup.name='Original geometry';pivotGroup.position.copy(pivot).negate();[...node.children].forEach(child=>pivotGroup.add(child));node.add(pivotGroup);
applyTransform(node,object);if(serial!==loadingSerial)return null;nodes.set(object.id,node);content.add(node);return node;}
function disposeContent(){particleEmitters.length=0;transform.detach();if(selectionBox){scene.remove(selectionBox);selectionBox.dispose();selectionBox=null;}content.traverse(o=>{if(o.isMesh)o.geometry.dispose();if(o.isSprite)o.material.dispose();});content.clear();nodes.clear();}
async function renderModel({fit=true}={}){const serial=++loadingSerial;state.loading=true;$('loading').hidden=false;$('loading-text').textContent=`Загрузка ${state.model.name}…`;disposeContent();state.unsupportedComponents=(state.model.objects||[]).flatMap(object=>(object.components||[]).filter(type=>!['position','lod','srb_lod','interface_plane','particle_emitter'].includes(type)).map(type=>({object:object.name,type})));state.unrenderedVideos=[];state.failedMeshes=[];state.failedTextures=[];state.failedMaterials=[];let done=0;const objects=state.model.objects;for(let i=0;i<objects.length;i+=5){await Promise.all(objects.slice(i,i+5).map(o=>renderObject(o,serial)));if(serial!==loadingSerial)return;done=Math.min(i+5,objects.length);$('loading-text').textContent=`${state.model.name} · объекты ${done} / ${objects.length}`;}state.loading=false;state.sceneLoads++;$('loading').hidden=true;renderTree();choose(nodes.has(state.selected)?state.selected:null);if(fit){if(state.model.camera?.present!==false)gameCamera();else frameAll();}const stats=geometryStats(content);status(`${state.model.name} · ${objects.length} объектов · ${Math.round(stats.faces).toLocaleString('ru-RU')} треугольников${state.failedMeshes.length?' · не загружено моделей: '+state.failedMeshes.length:''}`);if(state.failedMeshes.length){const failed=state.failedMeshes[0];toast(`Не удалось открыть ${state.failedMeshes.length} моделей. ${failed.mesh}: ${failed.error}`,true);}if(state.failedTextures.length||state.failedMaterials.length){const failed=state.failedTextures[0]||state.failedMaterials[0];status(`Ошибки ресурсов: ${state.failedTextures.length} текстур, ${state.failedMaterials.length} материалов · ${failed.name}: ${failed.error}`);toast(`Ресурс не загружен: ${failed.name}. ${failed.error}. Нажмите «Повторить загрузку».`,true);}$('retry-resources').hidden=!(state.failedMeshes.length||state.failedTextures.length||state.failedMaterials.length);}
function sceneEntries(){const entries=new Map((state.catalog?.scenes||[]).map(item=>[item.name,{...item,custom:false}]));for(const [name,model]of Object.entries(state.project.scenes||{}))if(!entries.has(name))entries.set(name,{name,objects:model.objects?.length||0,custom:true});return [...entries.values()].sort((a,b)=>a.name.localeCompare(b.name));}
function refreshSceneSelect(selected=state.model?.name){const entries=sceneEntries();$('scene-count').textContent=entries.length;$('scene-select').replaceChildren(...entries.map(item=>{const option=document.createElement('option');option.value=item.name;option.textContent=(item.custom?'★ ':'')+item.name;return option;}));if(selected)$('scene-select').value=selected;return entries;}
async function createScene(){let name=$('scene-new-name').value.trim();if(!/\.xml$/i.test(name))name+='.xml';if(!/^[a-z0-9_-]+\.xml$/i.test(name)||name.length>120)throw Error('Используйте имя из латинских букв, цифр, дефисов и подчёркиваний с расширением .xml');if(sceneEntries().some(item=>item.name.toLowerCase()===name.toLowerCase()))throw Error('Локация с таким именем уже существует');syncModel();const copy=currentSnapshot();copy.name=name;state.model=copy;state.project.scenes[name]=copy;state.selected=null;state.history=[];state.future=[];updateHistory();refreshSceneSelect(name);$('scene-dialog').close();markDirty();await renderModel();toast('Создана отдельная сцена. Сохраните проект или экспортируйте архив.');}
function captureCamera(){if(!state.model)return;remember();camera.updateMatrixWorld(true);const view=camera.matrixWorld.clone().invert(),rotation=new THREE.Euler().setFromRotationMatrix(view,'ZYX');state.model.camera={...(state.model.camera||{}),present:true,fov:camera.fov,position:new THREE.Vector3().setFromMatrixPosition(view).toArray(),rotation:[rotation.x,rotation.y,rotation.z].map(THREE.MathUtils.radToDeg)};$('view-name').textContent='Новый ракурс камеры сцены';toast('Свободный ракурс записан в камеру сцены');status('Камера изменена в проекте. Ctrl+Z — отменить');}
function openCameraProperties(){if(!state.model)return;const values=state.model.camera||{fov:50,position:[0,0,0],rotation:[0,0,0]};$('camera-fov').value=values.fov||50;$('camera-fields').innerHTML=['position','rotation'].map((key,i)=>`<div class="transform-row"><span>${['Позиция','Поворот°'][i]}</span>${['X','Y','Z'].map((axis,j)=>`<label class="axis-field"><span>${axis}</span><input type="number" step=".01" value="${Number(values[key]?.[j]||0).toFixed(4)}" data-camera-property="${key}" data-camera-axis="${j}" aria-label="Камера ${key} ${axis}"></label>`).join('')}</div>`).join('');$('camera-dialog').showModal();}
function applyCameraProperties(){const fov=Number($('camera-fov').value);if(!Number.isFinite(fov)||fov<5||fov>150)throw Error('Угол обзора должен быть от 5 до 150 градусов');const value={present:true,fov,position:[0,0,0],rotation:[0,0,0]};for(const input of $('camera-fields').querySelectorAll('input')){const number=Number(input.value);if(!Number.isFinite(number))throw Error('Параметры камеры должны быть числами');value[input.dataset.cameraProperty][Number(input.dataset.cameraAxis)]=number;}remember();state.model.camera=value;$('camera-dialog').close();gameCamera();toast('Камера сцены изменена');}
async function loadScene(name){if(!name)return;const requested=++requestedScene;syncModel();const saved=state.project.scenes[name];const model=saved?clone(saved):await api(`/api/scene?name=${encodeURIComponent(name)}`);if(requested!==requestedScene)return;model.name??=name;model.objects??=[];model.objects.forEach((o,i)=>{o.id??=`object-${i}`;o.name??=o.id;});state.model=model;state.selected=null;state.history=[];state.future=[];updateHistory();await renderModel();await loadSceneAnimations();}
function setTool(mode){if(mode!=='select-tool')leaveGameCamera();['select-tool','translate','rotate','scale'].forEach(id=>$(id).classList.toggle('active',id===mode));if(mode==='select-tool')transform.detach();else{transform.setMode(mode);if(selectedNode())transform.attach(selectedNode());}}
function fitBox(box){if(box.isEmpty()){camera.position.set(20,-30,20);orbit.target.set(0,0,0);return;}const center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()),radius=Math.max(size.length()/2,.5),dist=radius/Math.sin(THREE.MathUtils.degToRad(camera.fov/2));const dir=camera.position.clone().sub(orbit.target).normalize();if(!Number.isFinite(dir.x)||dir.lengthSq()<.1)dir.set(1,-1,.7).normalize();orbit.target.copy(center);camera.position.copy(center).addScaledVector(dir,dist*1.15);camera.near=Math.max(.001,radius/10000);camera.far=Math.max(10000,radius*1000);camera.updateProjectionMatrix();orbit.update();$('view-name').textContent='Свободная камера';}
function frameAll(){leaveGameCamera();fitBox(new THREE.Box3().setFromObject(content));}
function frameObject(){leaveGameCamera();if(selectedNode())fitBox(new THREE.Box3().setFromObject(selectedNode()));}
function renderRect(){const width=viewport.clientWidth,height=viewport.clientHeight;if(!gameCameraMode)return {x:0,y:0,top:0,width,height};const w=Math.min(width,height*4/3),h=w*3/4,x=(width-w)/2,y=(height-h)/2;return {x,y,top:y,width:w,height:h};}
function updateCameraViewport(){const rect=renderRect();const aspect=gameCameraMode?4/3:rect.width/Math.max(1,rect.height);if(camera.aspect!==aspect){camera.aspect=aspect;camera.updateProjectionMatrix();}}
function leaveGameCamera(){if(!gameCameraMode)return;gameCameraMode=false;grid.visible=gridPreferred;content.traverse(child=>{if(child.userData.editorHelper)child.visible=true;});if(selectionBox)selectionBox.visible=true;updateCameraViewport();$('view-name').textContent='Свободная камера';if(!$('select-tool').classList.contains('active')&&selectedNode())transform.attach(selectedNode());}
orbit.addEventListener('start',leaveGameCamera);
function gameCamera(){const source=state.model?.camera;if(!source){toast('В этой сцене нет исходной камеры',true);return;}const view=new THREE.Matrix4().makeRotationFromEuler(toEuler(source.rotation));view.setPosition(new THREE.Vector3().fromArray(vector(source.position)));const world=view.invert();camera.position.setFromMatrixPosition(world);camera.quaternion.setFromRotationMatrix(world);camera.fov=Number(source.fov)||50;camera.updateProjectionMatrix();gameCameraMode=true;grid.visible=false;content.traverse(child=>{if(child.userData.editorHelper)child.visible=false;});if(selectionBox)selectionBox.visible=true;transform.detach();updateCameraViewport();const direction=new THREE.Vector3(0,0,-1).applyQuaternion(camera.quaternion);orbit.target.copy(camera.position).addScaledVector(direction,10);$('view-name').textContent='Камера оригинальной сцены · 4:3';}
async function historyStep(redo=false){const source=redo?state.future:state.history,target=redo?state.history:state.future;if(!source.length)return;target.push(currentSnapshot());state.model=source.pop();markDirty();updateHistory();await renderModel({fit:false});}
async function duplicate(){const object=selectedObject();if(!object)return;remember();const copy=clone(object);copy.id=`editor-${crypto.randomUUID()}`;copy.name=(object.name||'Объект')+' — копия';copy.editorTransform??={position:[0,0,0],rotation:[0,0,0],scale:[1,1,1]};copy.editorTransform.position[0]+=1;state.model.objects.push(copy);await renderObject(copy,loadingSerial);choose(copy.id);status('Создана копия объекта');}
function remove(){const object=selectedObject();if(!object)return;remember();const node=selectedNode();content.remove(node);nodes.delete(object.id);state.model.objects=state.model.objects.filter(o=>o.id!==object.id);choose(null);status('Объект удалён из проекта. Ctrl+Z — отменить');}
async function addEmpty(){if(!state.model)return;remember();const object={id:`editor-${crypto.randomUUID()}`,name:'Новый объект',group:'static_objects',attributes:{},bones:[{id:0,parent:-1,name:'Root',position:[0,0,0],rotation:[0,0,0],scale:[1,1,1]}],lods:[],editorTransform:{position:orbit.target.toArray(),rotation:[0,0,0],scale:[1,1,1]}};state.model.objects.push(object);await renderObject(object,loadingSerial);choose(object.id);}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function safeName(name){return String(name||'scene').replace(/[<>:"/\\|?*\x00-\x1f]/g,'_');}
async function serverExport(format,object){syncModel();status('Готовим экспорт…');const res=await post('/api/export',{scene:state.model,format,...(object?{object}:{} )});if(!res.ok)throw Error(await res.text());download(await res.blob(),safeName(object?selectedObject()?.name:state.model.name)+(format==='obj'?'-obj.zip':'-project.zip'));toast('Экспорт готов');status('Экспорт завершён');}
async function exportGLB(objectOnly=false){const source=objectOnly?selectedNode():content;if(!source)return;transform.detach();const root=new THREE.Group();root.name=objectOnly?selectedObject().name:state.model.name;const copies=[];source.updateMatrixWorld(true);if(objectOnly){const copy=source.clone(true);root.add(copy);copies.push(copy);}else source.children.filter(c=>c.visible).forEach(c=>root.add(c.clone(true)));const helpers=[];root.traverse(o=>{if(o.userData.editorHelper)helpers.push(o);});helpers.forEach(o=>o.removeFromParent());root.traverse(o=>{if(o.isMesh){o.userData={};const mats=Array.isArray(o.material)?o.material:[o.material];o.material=mats.map(m=>new THREE.MeshStandardMaterial({name:m.name,color:m.color,map:m.map,transparent:m.transparent,alphaTest:m.alphaTest,side:THREE.DoubleSide,roughness:1,metalness:0}));if(o.material.length===1)o.material=o.material[0];}});status('Собираем GLB…');const data=await new GLTFExporter().parseAsync(root,{binary:true,onlyVisible:true});download(new Blob([data],{type:'model/gltf-binary'}),safeName(root.name)+'.glb');root.traverse(o=>{if(o.isMesh)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose());});if(!gameCameraMode&&!$('select-tool').classList.contains('active')&&selectedNode())transform.attach(selectedNode());toast('GLB сохранён');status('Экспорт GLB завершён');}
function serializeImported(root,name){const parts=[],materials=[];root.updateMatrixWorld(true);root.traverse(child=>{if(!child.isMesh)return;const geometry=child.geometry.clone();geometry.applyMatrix4(child.matrixWorld);const mats=Array.isArray(child.material)?child.material:[child.material],names=mats.map((m,i)=>`${name}-${parts.length}-${i}`);mats.forEach((m,i)=>{let data;const image=m.map?.image;if(image){try{const c=document.createElement('canvas');c.width=image.width;c.height=image.height;c.getContext('2d').drawImage(image,0,0);data=c.toDataURL('image/png');}catch(error){console.warn('Экспорт текстуры импорта',error);}}materials.push({name:names[i],color:m.color?.toArray()||[1,1,1],...(data?{texture:data,flipY:m.map.flipY}:{})});});const pos=geometry.attributes.position,uv=geometry.attributes.uv,indices=geometry.index?Array.from(geometry.index.array):Array.from({length:pos.count},(_,i)=>i),faceMaterials=Array(indices.length/3).fill(0);geometry.groups.forEach(group=>{for(let f=group.start/3;f<(group.start+group.count)/3;f++)faceMaterials[f]=group.materialIndex;});const expandedUV=[];for(const vi of indices)expandedUV.push(uv?.getX(vi)||0,uv?.getY(vi)||0);parts.push({name:child.name||name,positions:Array.from(pos.array),indices,uv:expandedUV,materialNames:names,faceMaterials});geometry.dispose();});if(!parts.length)throw Error('В файле нет полигональной геометрии');return {version:1,parts,materials};}
async function inspectResource(name){$('resource-title').textContent=name;$('resource-content').textContent='Загрузка…';$('resource-dialog').showModal();const response=await fetch(`/api/asset?name=${encodeURIComponent(name)}`);if(!response.ok)throw Error(await response.text());const bytes=new Uint8Array(await response.arrayBuffer());const sample=bytes.slice(0,Math.min(bytes.length,2048));const controls=[...sample].filter(b=>b===0||(b<32&&![9,10,13].includes(b))).length;if(controls>sample.length*.05){$('resource-content').textContent=`Двоичный ресурс · ${bytes.length.toLocaleString('ru-RU')} байт\n\n`+[...bytes.slice(0,256)].map(b=>b.toString(16).padStart(2,'0')).join(' ')+'\n\nЭто двоичный файл, а не текст исходного скрипта.';}else $('resource-content').textContent=new TextDecoder('windows-1251').decode(bytes);}
async function replaceModel(mesh,file){const object=selectedObject();if(!object||object.id!==state.importTarget)throw Error('Выделение изменилось. Выберите объект и повторите замену.');if((object.bones||[]).length>1)throw Error('Замена скелетных моделей пока не поддерживается');const bones=object.bones?.length?object.bones:[{id:0,parent:-1,name:'Root',position:[0,0,0],rotation:[0,0,0],scale:[1,1,1]}];const rootID=bones[0].id??0,world=boneMatrices({...object,bones}).get(String(rootID))||new THREE.Matrix4();if(Math.abs(world.determinant())<1e-12)throw Error('Невозможно заменить модель с нулевым масштабом корневой кости');const inverse=world.clone().invert(),point=new THREE.Vector3();for(const part of mesh.parts){for(let i=0;i<part.positions.length;i+=3){point.fromArray(part.positions,i).applyMatrix4(inverse);part.positions[i]=point.x;part.positions[i+1]=point.y;part.positions[i+2]=point.z;}part.vertexBones=Array(part.positions.length/3).fill(rootID);}remember();object.bones=bones;object.editorMesh=mesh;object.editorReplace=true;object.editorImported=false;object.editorReplacementSource=file.name;object.editorTransform={position:[0,0,0],rotation:[0,0,0],scale:[1,1,1]};const old=selectedNode();transform.detach();content.remove(old);old?.traverse(child=>{if(child.isMesh)child.geometry.dispose();});nodes.delete(object.id);await renderObject(object,loadingSerial);choose(object.id);toast('Модель заменена. Исходные свойства и скрипты объекта сохранены.');status('Замена геометрии в проекте. Ctrl+Z — отменить');}
async function importFile(file){if(!state.model)throw Error('Сначала выберите локацию');status(`Импорт ${file.name}…`);let root;const extension=file.name.split('.').pop().toLowerCase();if(extension==='obj')root=new OBJLoader().parse(await file.text());else if(extension==='glb'||extension==='gltf'){const data=extension==='glb'?await file.arrayBuffer():await file.text();const gltf=await new GLTFLoader().parseAsync(data,'');if(gltf.animations.length)throw Error('Импорт анимаций пока не поддерживается. Экспортируйте статическую модель.');root=gltf.scene;}else throw Error('Поддерживаются OBJ, GLB и glTF со встроенными ресурсами');let unsupported=false;root.traverse(o=>{if(o.isSkinnedMesh||o.morphTargetInfluences?.length)unsupported=true;});if(unsupported)throw Error('Скиннинг и морфинг пока не импортируются. Экспортируйте статическую геометрию.');const name=file.name.replace(/\.[^.]+$/,'');const mesh=serializeImported(root,name);if(state.importMode==='replace'){await replaceModel(mesh,file);return;}remember();const object={id:`editor-${crypto.randomUUID()}`,name,group:'Импортированные',attributes:{source:file.name},bones:[],lods:[],editorImported:true,editorMesh:mesh,editorTransform:{position:orbit.target.toArray(),rotation:[0,0,0],scale:[1,1,1]}};state.model.objects.push(object);await renderObject(object,loadingSerial);choose(object.id);frameObject();toast(`Импортировано: ${file.name}`);status('Модель добавлена в проект');}

const animationPreview={objects:[],bindings:new Map(),cache:new Map(),playing:false,time:0,duration:0,scope:'scene',speed:1,loop:true,last:null,lastPose:-1,generation:0};
function animationObject(){if(state.selected)return animationPreview.objects.find(item=>item.objectId===state.selected)||null;return animationPreview.scope==='scene'?animationPreview.objects[0]:null;}
function refreshAnimationClips(){if(typeof animationPreview==='undefined')return;const item=animationObject(),clips=item?.clips||[];const selected=animationPreview.bindings.get(item?.objectId)?.name;$('animation-clip').replaceChildren(...(!selected&&clips.length?[new Option('Выберите клип…','')]:[]),...(clips.length?clips.map(clip=>{const option=document.createElement('option');option.value=clip.name;option.textContent=clip.name;option.selected=clip.name===selected;return option;}):[new Option('Нет клипов','')]));$('animation-note').textContent=item?`${state.model?.objects.find(o=>o.id===item.objectId)?.name||item.objectId} · предпросмотр EZA · VM скриптов не запускается`:'В этой сцене не найдены ссылки на EZA';}
async function animationClip(name){if(!animationPreview.cache.has(name))animationPreview.cache.set(name,api(`/api/animation?name=${encodeURIComponent(name)}`).catch(error=>{animationPreview.cache.delete(name);throw error;}));return animationPreview.cache.get(name);}
